import React, { useState } from 'react';
import './App.css';

function App() {
  const [unlocked, setUnlocked] = useState(false);
  const [pin, setPin] = useState('9999');
  
  // Calculator state
  const [calcDisplay, setCalcDisplay] = useState('0');
  const [calcPrev, setCalcPrev] = useState(null);
  const [calcOp, setCalcOp] = useState(null);
  const [calcWaiting, setCalcWaiting] = useState(false);
  const [calcSecret, setCalcSecret] = useState('');
  const [calcAngleMode, setCalcAngleMode] = useState('deg');
  const [calcInv, setCalcInv] = useState(false);

  const factorial = (n) => {
    if (n < 0 || !Number.isInteger(n)) return NaN;
    if (n > 170) return Infinity;
    let result = 1;
    for (let i = 2; i <= n; i++) result *= i;
    return result;
  };

  const calcPress = (key) => {
    if (key === 'ac') {
      setCalcDisplay('0');
      setCalcPrev(null);
      setCalcOp(null);
      setCalcWaiting(false);
      setCalcSecret('');
      setCalcInv(false);
      return;
    }

    if (key === 'rad-toggle') {
      setCalcAngleMode(prev => (prev === 'deg' ? 'rad' : 'deg'));
      return;
    }

    if (key === 'inv') {
      setCalcInv(prev => !prev);
      return;
    }

    if (key === '⌫') {
      setCalcSecret(calcSecret.slice(0, -1));
      if (calcDisplay.length > 1 && calcDisplay !== 'Error') {
        setCalcDisplay(calcDisplay.slice(0, -1));
      } else {
        setCalcDisplay('0');
      }
      return;
    }

    const sciKeys = ['sin', 'cos', 'tan', 'log', 'ln', '√', 'π', 'e', '!'];
    if (sciKeys.includes(key)) {
      const num = parseFloat(calcDisplay);
      const toRad = (deg) => (deg * Math.PI) / 180;
      const angleInput = calcAngleMode === 'deg' ? toRad(num) : num;
      let result;
      
      switch (key) {
        case 'sin':
          result = calcInv ? (calcAngleMode === 'deg' ? (Math.asin(num) * 180) / Math.PI : Math.asin(num)) : Math.sin(angleInput);
          break;
        case 'cos':
          result = calcInv ? (calcAngleMode === 'deg' ? (Math.acos(num) * 180) / Math.PI : Math.acos(num)) : Math.cos(angleInput);
          break;
        case 'tan':
          result = calcInv ? (calcAngleMode === 'deg' ? (Math.atan(num) * 180) / Math.PI : Math.atan(num)) : Math.tan(angleInput);
          break;
        case 'log': result = calcInv ? Math.pow(10, num) : Math.log10(num); break;
        case 'ln': result = calcInv ? Math.exp(num) : Math.log(num); break;
        case '√': result = calcInv ? num * num : Math.sqrt(num); break;
        case 'π': result = Math.PI; break;
        case 'e': result = Math.E; break;
        case '!': result = factorial(num); break;
        default: result = num;
      }
      setCalcDisplay(isNaN(result) || result === undefined ? 'Error' : String(result));
      setCalcWaiting(true);
      setCalcSecret('');
      return;
    }

    if (key === '=') {
      if (calcSecret === pin) {
        setUnlocked(true);
        setCalcDisplay('0');
        setCalcSecret('');
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        return;
      }
      if (calcOp && !calcWaiting) {
        const num = parseFloat(calcDisplay);
        let result;
        switch (calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          case '^': result = Math.pow(calcPrev, num); break;
          default: result = num;
        }
        setCalcDisplay(isNaN(result) ? 'Error' : String(result));
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        setCalcSecret('');
        return;
      }
      setCalcSecret('');
      return;
    }

    if (/^[0-9]$/.test(key)) {
      setCalcSecret(calcSecret + key);
      if (calcWaiting) {
        setCalcDisplay(key);
        setCalcWaiting(false);
      } else {
        setCalcDisplay(calcDisplay === '0' ? key : calcDisplay + key);
      }
      return;
    }

    if (key === '.') {
      if (calcWaiting) {
        setCalcDisplay('0.');
        setCalcWaiting(false);
        return;
      }
      if (!calcDisplay.includes('.')) {
        setCalcDisplay(calcDisplay + '.');
      }
      return;
    }

    if (['+', '-', '×', '÷', '^'].includes(key)) {
      const num = parseFloat(calcDisplay);
      if (calcOp && !calcWaiting) {
        let result;
        switch (calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          case '^': result = Math.pow(calcPrev, num); break;
          default: result = num;
        }
        setCalcDisplay(String(isNaN(result) ? 'Error' : result));
        setCalcPrev(isNaN(result) ? 0 : result);
        setCalcOp(key);
        setCalcWaiting(true);
      } else {
        setCalcPrev(num);
        setCalcOp(key);
        setCalcWaiting(true);
      }
      return;
    }

    if (key === '±') {
      if (calcDisplay !== '0' && calcDisplay !== 'Error') {
        setCalcDisplay(calcDisplay.startsWith('-') ? calcDisplay.slice(1) : '-' + calcDisplay);
      }
      return;
    }

    if (key === '%') {
      const num = parseFloat(calcDisplay);
      setCalcDisplay(String(num / 100));
      return;
    }
  };

  if (unlocked) {
    return (
      <div id="stage">
        <div id="phone">
          <div id="sanctuary">
            <h1>🔓 Unlocked</h1>
            <p>Welcome to AURA Sanctuary</p>
            <button onClick={() => setUnlocked(false)}>Lock</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div id="stage">
      <div id="phone">
        <div className="calc-screen">
          <div className="calc-clock">08:18</div>
          <div className="calc-display-wrap">
            <div className="calc-display">{calcDisplay}</div>
          </div>
          <div className="calc-pad">
            {/* Row 1 */}
            <button className="calc-btn fn" onClick={() => calcPress('√')}>√</button>
            <button className="calc-btn fn" onClick={() => calcPress('π')}>π</button>
            <button className="calc-btn fn" onClick={() => calcPress('^')}>^</button>
            <button className="calc-btn fn" onClick={() => calcPress('!')}>!</button>

            {/* Row 2 */}
            <button className="calc-btn fn" onClick={() => calcPress('rad-toggle')}>
              {calcAngleMode === 'deg' ? 'Deg' : 'Rad'}
            </button>
            <button className="calc-btn fn" onClick={() => calcPress('sin')}>sin</button>
            <button className="calc-btn fn" onClick={() => calcPress('cos')}>cos</button>
            <button className="calc-btn fn" onClick={() => calcPress('tan')}>tan</button>

            {/* Row 3 */}
            <button className="calc-btn fn" onClick={() => calcPress('inv')}>Inv</button>
            <button className="calc-btn fn" onClick={() => calcPress('e')}>e</button>
            <button className="calc-btn fn" onClick={() => calcPress('ln')}>ln</button>
            <button className="calc-btn fn" onClick={() => calcPress('log')}>log</button>

            {/* Row 4 */}
            <button className="calc-btn fn" onClick={() => calcPress('ac')}>AC</button>
            <button className="calc-btn" style={{ opacity: '0.4', cursor: 'default' }}>(</button>
            <button className="calc-btn" style={{ opacity: '0.4', cursor: 'default' }}>)</button>
            <button className="calc-btn fn" onClick={() => calcPress('%')}>%</button>
            <button className="calc-btn op" onClick={() => calcPress('÷')}>÷</button>

            {/* Row 5 */}
            <button className="calc-btn" onClick={() => calcPress('7')}>7</button>
            <button className="calc-btn" onClick={() => calcPress('8')}>8</button>
            <button className="calc-btn" onClick={() => calcPress('9')}>9</button>
            <button className="calc-btn op" onClick={() => calcPress('×')}>×</button>

            {/* Row 6 */}
            <button className="calc-btn" onClick={() => calcPress('4')}>4</button>
            <button className="calc-btn" onClick={() => calcPress('5')}>5</button>
            <button className="calc-btn" onClick={() => calcPress('6')}>6</button>
            <button className="calc-btn op" onClick={() => calcPress('-')}>−</button>

            {/* Row 7 */}
            <button className="calc-btn" onClick={() => calcPress('1')}>1</button>
            <button className="calc-btn" onClick={() => calcPress('2')}>2</button>
            <button className="calc-btn" onClick={() => calcPress('3')}>3</button>
            <button className="calc-btn op" onClick={() => calcPress('+')}>+</button>

            {/* Row 8 */}
            <button className="calc-btn zero" onClick={() => calcPress('0')}>0</button>
            <button className="calc-btn" onClick={() => calcPress('.')}>.</button>
            <button className="calc-btn fn" onClick={() => calcPress('⌫')}>⌫</button>
            <button className="calc-btn op" onClick={() => calcPress('=')}>=</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
